const TL=['','Architects','Contention','Top-10 Range','Cut-Line','Course Mismatches'];
const APS={bomb_and_spray:'B&S',short_and_wild:'S&W',long_iron_liability:'LI',weak_tight_runoff:'WkRO',poor_lag_putting:'LagP'};

function pill(t){return `<span class="tpill tp${t}">T${t}: ${TL[t]||''}</span>`;}
function chips(fl,rfg,dc){
  let s=(fl||[]).map(f=>`<span class="fchip">${APS[f]||f}</span>`).join('');
  if(rfg) s+=`<span class="fchip form">Gate</span>`;
  if(dc&&dc!=='none') s+=`<span class="fchip debut">Dbt</span>`;
  return s;
}

document.addEventListener('DOMContentLoaded',()=>{
  buildSidebar(); buildHero(); buildTours(); setupEvents(); renderTable();
});

function buildSidebar(){
  const tc=PAYLOAD.model_summary.tier_counts;
  $('cnt-all').textContent=PAYLOAD.model_summary.total_players;
  for(let t=1;t<=5;t++) $('cnt-'+t).textContent=tc['tier_'+t]||0;
  const rew=['OTT Accuracy','Wind Tolerance','Lag Putting','Tight Runoff','APP Precision'];
  const pun=['Bomb & Spray','Long Iron Liab','Short & Wild','Wk Runoff','Lag Putt Gap'];
  $('dna-r').innerHTML='<div class="dna-chips">'+rew.map(r=>`<span class="chip-pos">${r}</span>`).join('')+'</div>';
  $('dna-p').innerHTML='<div class="dna-chips">'+pun.map(r=>`<span class="chip-neg">${r}</span>`).join('')+'</div>';
  $('wx').innerHTML=PAYLOAD.venue.weather.map(w=>`<div class="wx-row${w.stars>=3?' hard':''}"><span class="wx-rd">${w.rd} ${w.day}</span><span class="wx-w">${w.wind}</span></div>`).join('');
}

function buildHero(){
  const ms=PAYLOAD.model_summary;
  const wc=ms.winner_card,hc=ms.hero_cards;
  const cards=[
    {l:'Highest Venue Fit',c:hc.highest_venue_fit},
    {l:'Cleanest Profile',c:hc.cleanest_profile},
    {l:'Biggest AP Fade',c:hc.biggest_fade},
    {l:'Safest Cut',c:hc.safest_cut},
  ];
  let h=`<div class="hgrid">
    <div class="hw" onclick="odr(${wc.model_rank})">
      <div class="hw-lbl">⟡ Model Top Pick</div>
      <div class="hw-name">${wc.player_name}</div>
      <div class="hw-vts">${f1(wc.vts_final)} <small style="font-size:13px;color:var(--tx2)">VTS</small></div>
      <div class="hw-sub">Win: ${fp(wc.win_pct)} · MC: ${fp(wc.make_cut_pct)} · ${pill(wc.tier)}</div>
      <div class="hw-why">${wc.reason}</div>
    </div>`;
  cards.forEach(x=>{
    const c=x.c;
    h+=`<div class="hcard" onclick="odr(${c.model_rank})">
      <div class="hc-lbl">${x.l}</div>
      ${pill(c.tier)}
      <div class="hc-name">${c.player_name}</div>
      <div class="hc-vts">${f1(c.vts_final)} VTS</div>
      <div class="hc-why">${c.reason}</div>
    </div>`;
  });
  $('hero').innerHTML=h+'</div>';
}

function buildTours(){
  const tours=[...new Set(PAYLOAD.players.map(p=>p.tour||'Unknown'))].sort();
  const sel=$('f-tour');
  tours.forEach(t=>{const o=document.createElement('option');o.value=t;o.textContent=t;sel.appendChild(o);});
}

function setupEvents(){
  $('tnav-wrap').querySelectorAll('.tnav').forEach(b=>{
    b.addEventListener('click',()=>{
      $('tnav-wrap').querySelectorAll('.tnav').forEach(x=>x.classList.remove('active'));
      b.classList.add('active');
      ST.tier=b.dataset.tier; $('f-tier').value=b.dataset.tier; renderTable();
    });
  });
  $('q').addEventListener('input',e=>{ST.q=e.target.value.toLowerCase();renderTable();});
  $('f-tier').addEventListener('change',e=>{
    ST.tier=e.target.value;
    $('tnav-wrap').querySelectorAll('.tnav').forEach(b=>b.classList.remove('active'));
    $('tnav-wrap').querySelector(`[data-tier="${e.target.value}"]`)?.classList.add('active');
    renderTable();
  });
  $('f-tour').addEventListener('change',e=>{ST.tour=e.target.value;renderTable();});
  $('f-anti').addEventListener('change',e=>{ST.anti=e.target.value;renderTable();});
  $('f-gate').addEventListener('change',e=>{ST.gate=e.target.value;renderTable();});
  $('reset-btn').addEventListener('click',resetAll);
  document.querySelectorAll('.sort-h').forEach(th=>{
    th.addEventListener('click',()=>{
      const k=th.dataset.k;
      if(!k) return;
      if(ST.sk===k) ST.sd=ST.sd==='asc'?'desc':'asc';
      else{ST.sk=k;ST.sd=k==='model_rank'?'asc':'desc';}
      document.querySelectorAll('.sort-h').forEach(t=>t.classList.remove('asc','desc'));
      th.classList.add(ST.sd);
      renderTable();
    });
  });
  $('close-btn').addEventListener('click',closeD);
  $('overlay').addEventListener('click',closeD);
}

function resetAll(){
  ST.q='';ST.tier='all';ST.tour='all';ST.anti='all';ST.gate='all';
  $('q').value='';$('f-tier').value='all';$('f-tour').value='all';
  $('f-anti').value='all';$('f-gate').value='all';
  $('tnav-wrap').querySelectorAll('.tnav').forEach(b=>b.classList.remove('active'));
  $('tnav-wrap').querySelector('[data-tier="all"]').classList.add('active');
  renderTable();
}

function getFilt(){
  return PAYLOAD.players.filter(p=>{
    if(ST.q&&!p.player_name.toLowerCase().includes(ST.q)) return false;
    if(ST.tier!=='all'&&p.tier!==parseInt(ST.tier)) return false;
    if(ST.tour!=='all'&&p.tour!==ST.tour) return false;
    if(ST.anti==='clean'&&p.anti_pattern_flags.length>0) return false;
    if(ST.anti==='flagged'&&p.anti_pattern_flags.length===0) return false;
    if(ST.gate==='gated'&&!p.recent_form_gate_applied&&p.health_gate_status==='ok') return false;
    if(ST.gate==='clean'&&(p.recent_form_gate_applied||p.health_gate_status!=='ok')) return false;
    return true;
  });
}

function srt(arr){
  const k=ST.sk,dir=ST.sd==='asc'?1:-1;
  return [...arr].sort((a,b)=>{
    const av=a[k],bv=b[k];
    if(typeof av==='string') return dir*av.localeCompare(bv);
    return dir*((av??-Infinity)-(bv??-Infinity));
  });
}

function renderTable(){
  const data=srt(getFilt());
  $('n-showing').textContent=data.length;
  $('tbody').innerHTML=data.map(p=>`
    <tr class="t${p.tier}" onclick="odr(${p.model_rank})">
      <td class="td-rank">${p.model_rank}</td>
      <td class="td-name">${p.player_name}<span class="td-sub">${p.tour||''}</span></td>
      <td>${pill(p.tier)}</td>
      <td class="num" style="color:var(--t${p.tier});font-family:var(--fn);font-size:13px;font-weight:600">${f1(p.vts_final)}</td>
      <td class="num ${cl(p.neutral_skill_sg)}">${sg1(p.neutral_skill_sg)}</td>
      <td class="num ${cl(p.venue_fit_delta)}">${sg1(p.venue_fit_delta)}</td>
      <td class="num ${cl(p.venue_history_delta)}">${p.venue_history_delta===0?'—':sg1(p.venue_history_delta)}</td>
      <td class="num ${p.anti_pattern_penalty_total<0?'neg':'neu'}">${p.anti_pattern_penalty_total!==0?sg1(p.anti_pattern_penalty_total):'—'}</td>
      <td class="td-flags">${chips(p.anti_pattern_flags,p.recent_form_gate_applied,p.debut_class)}</td>
      <td class="num">${fp(p.win_pct)}</td>
      <td class="num">${fp(p.top10_pct)}</td>
      <td class="num ${p.make_cut_pct>=70?'pos':p.make_cut_pct<=40?'neg':'neu'}">${fp(p.make_cut_pct)}</td>
      <td class="num">${f2(p.volatility_index)}</td>
      <td style="font-family:var(--fn);font-size:11px;color:var(--tx2);white-space:nowrap">${p.tee_time_rd1||'—'}</td>
    </tr>`).join('');
}

function odr(rank){
  const p=PAYLOAD.players.find(x=>x.model_rank===rank);
  if(!p) return;
  buildDrawer(p);
  $('drawer').classList.remove('hidden');
  $('overlay').classList.remove('hidden');
}

function closeD(){
  $('drawer').classList.add('hidden');
  $('overlay').classList.add('hidden');
}

function db(val,max,cls){
  const pct=Math.max(0,Math.min(100,Math.abs(val)/max*100));
  return `<div class="dbar-w"><div class="dbar ${cls}" style="width:${pct}%"></div></div>`;
}

function buildDrawer(p){
  const apmap=[
    ['Bomb & Spray',p.ap_bomb_and_spray],['Short & Wild',p.ap_short_and_wild],
    ['Long Iron',p.ap_long_iron_liability],['Weak Runoff',p.ap_weak_tight_runoff],['Lag Putt',p.ap_poor_lag_putting]
  ].filter(([,v])=>v!==0);
  const fi=p.recent_form_gate_applied?'⚠ GATED':(p.form_vs_neutral>=0.5?'↑ Above baseline':p.form_vs_neutral<=-0.5?'↓ Below baseline':'→ On baseline');
  
  let h=`
  <div class="d-meta">
    <span class="d-rank">#${p.model_rank}</span>
    ${pill(p.tier)}
    ${p.recent_form_gate_applied?'<span class="fchip form">Form Gate</span>':''}
    ${p.debut_class&&p.debut_class!=='none'?`<span class="fchip debut">Debut ${p.debut_class}</span>`:''}
  </div>
  <div class="d-name">${p.player_name}</div>
  <div class="d-tour">World Rank <span>#${p.world_rank}</span> · <span>${p.tour||'Unknown'}</span></div>
  ${p.tee_time_rd1?`<div class="tee-row"><span class="tee-lbl">R1 Tee Time</span><span class="tee-val">${p.tee_time_rd1}</span></div>`:''}
  
  <div class="pstrip">
    <div class="pcell"><div class="plbl">Win</div><div class="pval">${fp(p.win_pct)}</div></div>
    <div class="pcell"><div class="plbl">Top 3</div><div class="pval">${fp(p.top3_pct)}</div></div>
    <div class="pcell"><div class="plbl">Top 5</div><div class="pval">${fp(p.top5_pct)}</div></div>
    <div class="pcell"><div class="plbl">Top 10</div><div class="pval">${fp(p.top10_pct)}</div></div>
    <div class="pcell"><div class="plbl">Top 20</div><div class="pval">${fp(p.top20_pct)}</div></div>
    <div class="pcell"><div class="plbl">Make Cut</div><div class="pval gr">${fp(p.make_cut_pct)}</div></div>
  </div>

  <div class="decomp">
    <div class="decomp-ttl">VTS Score Decomposition</div>
    <div class="drow"><div class="dlbl">Neutral Skill</div>${db(p.neutral_skill_index,100,'db-sk')}<div class="dval" style="color:var(--bl2)">${f1(p.neutral_skill_index)}</div></div>
    <div class="drow"><div class="dlbl">Venue Fit Δ</div>${db(p.venue_fit_delta,15,p.venue_fit_delta>=0?'db-fp':'db-fn')}<div class="dval ${cl(p.venue_fit_delta)}">${sg1(p.venue_fit_delta)}</div></div>
    <div class="drow"><div class="dlbl">History Δ</div>${db(p.venue_history_delta,15,p.venue_history_delta>=0?'db-hp':'db-hn')}<div class="dval ${cl(p.venue_history_delta)}">${p.venue_history_delta===0?'—':sg1(p.venue_history_delta)}</div></div>
    <hr class="ddiv">
    <div class="drow"><div class="dlbl" style="color:var(--tx)">Pre-Penalty VTS</div>${db(p.pre_penalty_vts,100,'db-fi')}<div class="dval" style="color:var(--gold)">${f1(p.pre_penalty_vts)}</div></div>
    ${p.anti_pattern_penalty_total!==0?`<div class="drow"><div class="dlbl" style="color:var(--or)">AP Penalties</div>${db(Math.abs(p.anti_pattern_penalty_total),20,'db-pe')}<div class="dval neg">${sg1(p.anti_pattern_penalty_total)}</div></div>`:''}
    ${p.debut_penalty_applied!==0?`<div class="drow"><div class="dlbl" style="color:var(--bl2)">Debut Penalty</div>${db(Math.abs(p.debut_penalty_applied),20,'db-pe')}<div class="dval neg">${sg1(p.debut_penalty_applied)}</div></div>`:''}
    <hr class="ddiv">
    <div class="drow"><div class="dlbl" style="color:var(--gold2);font-weight:700">VTS Final</div>${db(p.vts_final,100,'db-fi')}<div class="dval" style="color:var(--gold2);font-size:15px;font-weight:700">${f1(p.vts_final)}</div></div>
  </div>

  <div class="dsec">
    <div class="dstitle">Trait Profile</div>
    <div class="trbadges"><span class="trb trb-p">${p.primary_trait_driver||'—'}</span><span class="trb trb-n">Risk: ${p.primary_risk_trait||'—'}</span></div>
    <div class="dtxt">${p.trait_summary_label||''}</div>
  </div>

  ${p.brief_text?`<div class="dsec"><div class="dstitle">Player Brief</div><div class="dtxt brief">${p.brief_text.split('\n').join('<br>')}</div></div>`:''}

  <div class="dsec"><div class="dstitle">Neutral Skill</div><div class="dtxt">${p.neutral_skill_summary}</div></div>
  <div class="dsec"><div class="dstitle">Shinnecock Venue Fit</div><div class="dtxt">${p.venue_fit_summary}</div></div>
  <div class="dsec"><div class="dstitle">Venue History</div><div class="dtxt">${p.venue_history_summary}</div></div>
  <div class="dsec"><div class="dstitle">Recent Form — ${fi}</div><div class="dtxt">${p.form_summary}</div></div>

  ${p.anti_pattern_flags&&p.anti_pattern_flags.length?`<div class="dsec">
    <div class="dstitle">Anti-Pattern Analysis</div>
    <div class="dtxt">${p.anti_pattern_summary}</div>
    ${apmap.length?`<div class="apbr">${apmap.map(([l,v])=>`<div class="aprow"><span class="aplbl">${l}</span><span class="apval">${sg1(v)} VTS</span></div>`).join('')}</div>`:''}
  </div>`:''}

  <div class="dsec"><div class="dstitle">Penalties & Gates</div><div class="dtxt">${p.penalties_summary}</div></div>
  <div class="dsec"><div class="dstitle">Risk Vector</div><div class="dtxt warn">${p.risk_vector}</div></div>
  <div class="dsec"><div class="dstitle">Conviction</div><div class="cbox"><div class="dtxt">${p.conviction_statement}</div></div></div>
  <div class="dsec"><div class="dstitle">Failure Condition</div><div class="fbox"><div class="dtxt">${p.failure_condition}</div></div></div>
  ${p.trace_notes?`<div class="dsec"><div class="dstitle">Model Trace</div><div class="dtxt" style="font-family:var(--fn);font-size:11px;color:var(--tx3)">${p.trace_notes}</div></div>`:''}
  `;
  $('dc').innerHTML=h;
}

window.odr=odr;
